INSERT INTO posts (author_id, kind, body, passage_book, passage_ch, likes_count, comments_count, created_at) VALUES ((SELECT id FROM users WHERE display_name = 'Grace Chapel Lagos' AND clerk_id LIKE 'demo_%' LIMIT 1), 'Announcement', 'Sunday services at 9:00 and 11:00. This week we continue our series in the Gospel of John — bring a friend!', 'JHN', 3, 48, 0, now() - interval '3 hours');
INSERT INTO posts (author_id, kind, body, passage_book, passage_ch, likes_count, comments_count, created_at) VALUES ((SELECT id FROM users WHERE display_name = 'Rev. Esther Mwangi' AND clerk_id LIKE 'demo_%' LIMIT 1), 'Reflection', '“The Lord is my shepherd; I shall not want.” Wanting less is not the same as having less. Today, notice what you already have.', 'PSA', 23, 112, 0, now() - interval '6 hours');
