INSERT INTO jobs (client_id, kind, title, description, category, budget, deadline, skills, created_at) VALUES ((SELECT id FROM users WHERE display_name = 'Wycliffe Global Partners' AND clerk_id LIKE 'demo_%' LIMIT 1), 'job', 'Senior React Native Developer for Bible Translation App', 'We are expanding our mobile Scripture delivery platform to reach 50+ regional languages. Seeking an experienced React Native developer passionate about spreading God''s Word.', 'Software & Web Development', '$3,500 – $4,500 / mo', 'Full-time · Remote', ARRAY['React Native','Expo','TypeScript','Offline SQLite','Hermes']::text[], now() - interval '46 hours');
INSERT INTO jobs (client_id, kind, title, description, category, budget, deadline, skills, created_at) VALUES ((SELECT id FROM users WHERE display_name = 'Grace Spring Church' AND clerk_id LIKE 'demo_%' LIMIT 1), 'task', 'Edit 5 Sermon Videos for Social Reels & YouTube Shorts', 'Cut 5 high-impact clips (under 60s) from our Sunday service. Add accurate subtitles, royalty-free background pad, and clean brand hooks.', 'Graphic Design & Video Editing', '$250 Fixed', '5 Days Delivery', ARRAY['Premiere Pro','CapCut','Subtitles/Captions','Color Grading']::text[], now() - interval '50 hours');
INSERT INTO jobs (client_id, kind, title, description, category, budget, deadline, skills, created_at) VALUES ((SELECT id FROM users WHERE display_name = 'Pastor Ade' AND clerk_id LIKE 'demo_%' LIMIT 1), 'task', 'Virtual Assistant for Church Outreach Administration', 'Help coordinate visitor follow-ups, prayer request logging, and monthly event reminders for a congregation of 500 members.', 'Virtual Assistants', '$400 / month', '10 hrs/week · Ongoing', ARRAY['Email Management','Google Sheets','Calendar Coordination','Member Care']::text[], now() - interval '54 hours');
INSERT INTO jobs (client_id, kind, title, description, category, budget, deadline, skills, created_at) VALUES ((SELECT id FROM users WHERE display_name = 'Zion Sound Records' AND clerk_id LIKE 'demo_%' LIMIT 1), 'job', 'Worship Music Producer / Mixing Engineer', 'Production and mixing for a 3-track acoustic worship EP. Looking for a producer with deep appreciation for atmospheric sacred music.', 'Worship Musicians & Producers', '$800 per EP Track', 'Contract · 3 Tracks', ARRAY['Logic Pro / Pro Tools','Vocal Tuning','Mastering','Acoustic Guitar Mixing']::text[], now() - interval '58 hours');
INSERT INTO jobs (client_id, kind, title, description, category, budget, deadline, skills, created_at) VALUES ((SELECT id FROM users WHERE display_name = 'West Africa Gospel Network' AND clerk_id LIKE 'demo_%' LIMIT 1), 'task', 'Translate 20 Devotional Articles from English to Yoruba', 'Faithful translation of 20 daily devotional guides into standard written Yoruba with proper diacritics and scripture accuracy.', 'Writers, Editors & Translators', '$300 Fixed', '2 Weeks', ARRAY['Yoruba Fluency','Theological Translation','Proofreading']::text[], now() - interval '62 hours');
